<script setup>
import{Head,Link,router}from'@inertiajs/vue3';import{ref}from'vue';import AppLayout from'../../../Layouts/AppLayout.vue';import ConfirmDialog from'../../../Components/ConfirmDialog.vue';
const props=defineProps({batch:Object,rows:Object});const confirming=ref(false);const busy=ref(false);const run=()=>{busy.value=true;router.post(`/admin/student-imports/${props.batch.id}/execute`,{}, {onFinish:()=>{busy.value=false;confirming.value=false}})}
</script>
<template><AppLayout><Head title="نتیجه ورود گروهی"/><div class="space-y-5"><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">{{batch.status==='VALIDATED'?'مرحله ۲ — بررسی و پیش‌نمایش':'مرحله ۳ — نتیجه'}}</h1><div class="mt-4 grid gap-3 sm:grid-cols-4"><p>کل: {{batch.total_rows}}</p><p>جدید معتبر: {{batch.valid_rows}}</p><p>موجود: {{batch.matched_existing_users}}</p><p>نامعتبر: {{batch.invalid_rows+batch.duplicate_rows}}</p><p>ساخته‌شده: {{batch.created_users}}</p><p>ثبت‌نام: {{batch.created_enrollments}}</p></div><div class="mt-4 flex flex-wrap gap-3"><button v-if="batch.status==='VALIDATED'" class="rounded-xl bg-teal-700 px-5 py-2 text-white" @click="confirming=true">ورود اطلاعات</button><a :href="`/admin/student-imports/${batch.id}/errors`" class="rounded-xl border px-5 py-2">گزارش خطا CSV</a><Link href="/admin/student-imports" class="rounded-xl border px-5 py-2">بازگشت</Link></div></section><section class="overflow-x-auto rounded-2xl border bg-white p-5"><table class="w-full min-w-[700px] text-sm"><thead><tr><th>ردیف</th><th>نام</th><th>موبایل</th><th>ایمیل</th><th>نتیجه</th><th>خطا</th></tr></thead><tbody><tr v-for="r in rows.data" :key="r.id" class="border-t"><td>{{r.row_number}}</td><td>{{r.data.first_name}} {{r.data.last_name}}</td><td dir="ltr">{{r.data.mobile}}</td><td>{{r.data.email}}</td><td>{{r.status}}</td><td>{{r.error_message}}</td></tr></tbody></table><p v-if="!rows.data.length" class="p-6 text-center text-slate-500">ردیفی برای نمایش وجود ندارد.</p></section></div><ConfirmDialog :open="confirming" title="تأیید ورود اطلاعات" message="پس از تأیید، هنرجویان معتبر و ثبت‌نام‌های انتخاب‌شده ایجاد می‌شوند." confirm-label="تأیید و اجرا" :busy="busy" @cancel="confirming=false" @confirm="run"/></AppLayout></template>
